    if 'constructedArithmeticExample' in m:
        c=m['constructedArithmeticExample'];parts += [text_in_lang(c['label'],lang),json.dumps({k:v for k,v in c.items() if k not in ['label','expectedCalculation']},ensure_ascii=False),text_in_lang(c['expectedCalculation'],lang)]
    if m['caseId']=='lab15-06-b-synthesis-purity-v2':parts += [asa_add[lang],asa_fresh_solution[lang]]
    if m['caseId']=='bcp-biotechnological-preparation-b':parts += [('Die tatsächlich ausgeführten Kontrollbedingungen trennen soweit möglich Stärke, Enzymträger und lebende Hefe. H gegenüber I/N ist nur zusammen mit E/EI und G interpretierbar; das AMG-Präparat kann selbst vergärbare Zucker enthalten. G prüft Hefefunktion unter dieser Citratmatrix. Ein Nullbefund ist ein Ergebnis, kein Anlass zur erfundenen Gasmenge. Filtrat bleibt ein unreines biologisches Präparat; fehlende Produktanalytik verhindert einen Ethanol-/Glucosereinheitsanspruch.' if lang=='de' else 'Interpret H versus I/N and raw R together with E/EI and G: the AMG preparation can itself contain fermentable sugars. G tests yeast function in this citrate matrix. A null result is a valid outcome, never a reason to invent gas volumes. Filtrate remains an impure biological preparation; absent selective analysis precludes ethanol/glucose purity claims.')]
    return '\n\n'.join(x for x in parts if x)

